from itertools import combinations

def search():
    for subset in combinations(range(16), 9):
        # must include 0 and 15 for edge diff 15
        if 0 not in subset or 15 not in subset:
            continue
        # try permutations
        for perm in permutations(subset):
            diffs = set()
            ok = True
            for u,v in edges:
                d = abs(perm[u]-perm[v])
                if d==0 or d in diffs:
                    ok=False; break
                diffs.add(d)
            if ok:
                return perm
    return None

