import sys
sys.setrecursionlimit(100000)

def backtrack(assigned, used_labels, used_diffs):
    v = len(assigned)
    if v == 9:
        return list(assigned)
    for lab in range(16):
        if lab in used_labels: continue
        new_diffs = []
        ok = True
        for u,w in edges:
            if w == v and u < v:
                d = abs(assigned[u]-lab)
                if d in used_diffs or d in new_diffs:
                    ok=False; break
                new_diffs.append(d)
            elif u == v and w < v:
                d = abs(assigned[w]-lab)
                if d in used_diffs or d in new_diffs:
                    ok=False; break
                new_diffs.append(d)
        if not ok: continue
        assigned.append(lab)
        used_labels.add(lab)
        for d in new_diffs: used_diffs.add(d)
        r = backtrack(assigned, used_labels, used_diffs)
        if r: return r
        assigned.pop()
        used_labels.remove(lab)
        for d in new_diffs: used_diffs.remove(d)
    return None

